// ── Animations ───────────────────────────────────────────────────────────────

const scrollUp = keyframes`
  0%   { transform: translateY(0); }
  100% { transform: translateY(-50%); }
`;

const newGlow = keyframes`
  0%   { box-shadow: 0 8px 24px rgba(0,0,0,0.55), 0 0  0px  0px rgba(232,80,240,0);    }
  20%  { box-shadow: 0 8px 24px rgba(0,0,0,0.55), 0 0 40px 14px rgba(232,80,240,0.85); }
  60%  { box-shadow: 0 8px 24px rgba(0,0,0,0.55), 0 0 24px  6px rgba(168,85,247,0.5);  }
  100% { box-shadow: 0 8px 24px rgba(0,0,0,0.55), 0 24px 64px rgba(168,85,247,0.08);   }
`;

const dropIn = keyframes`
  0%   { opacity: 0; transform: translateY(-60px) scale(0.85) rotate(var(--rot)); }
  60%  { opacity: 1; transform: translateY(8px)   scale(1.04) rotate(var(--rot)); }
  100% { opacity: 1; transform: translateY(0)     scale(1)    rotate(var(--rot)); }
`;

// ── Deterministic rotation (-4° to +4°) ─────────────────────────────────────

const getRotation = (id = "") => {
  const sum = id.split("").reduce((a, c) => a + c.charCodeAt(0), 0);
  return ((sum % 9) - 4);
};

